  return result;
});

int _textureGetSampleCount(Texture texture) => ffi.using((allocator) {
  final result = bindings.wgpuTextureGetSampleCount(texture._ptr);
  return result;
});

TextureViewDimension _textureGetTextureBindingViewDimension(Texture texture) => ffi.using((allocator) {
  final result = bindings.wgpuTextureGetTextureBindingViewDimension(texture._ptr);
  return TextureViewDimension.fromNative(result);
});

TextureUsage _textureGetUsage(Texture texture) => ffi.using((allocator) {
  final result = bindings.wgpuTextureGetUsage(texture._ptr);
  return TextureUsage(result);
});

int _textureGetWidth(Texture texture) => ffi.using((allocator) {
  final result = bindings.wgpuTextureGetWidth(texture._ptr);
  return result;
});

void _texturePin(Texture texture, TextureUsage usage) => ffi.using((allocator) {
  bindings.wgpuTexturePin(texture._ptr, usage.value);
});

void _textureSetLabel(Texture texture, String label) => ffi.using((allocator) {
  bindings.wgpuTextureSetLabel(texture._ptr, StringView(data: label, length: label.length).toNative(allocator).ref);
});

void _textureSetOwnershipForMemoryDump(Texture texture, int ownerGuid) => ffi.using((allocator) {
  bindings.wgpuTextureSetOwnershipForMemoryDump(texture._ptr, ownerGuid);
});

void _textureUnpin(Texture texture) => ffi.using((allocator) {
  bindings.wgpuTextureUnpin(texture._ptr);
});

void _textureViewSetLabel(TextureView textureView, String label) => ffi.using((allocator) {
  bindings.wgpuTextureViewSetLabel(textureView._ptr, StringView(data: label, length: label.length).toNative(allocator).ref);
});
